85	    );
86	    const ret: Array<string | Array<string | ImageURL>> =
87	      addSystem && system_prompt !== "" ? [system_prompt] : [];
88	
89	    // Process each message in this.messages
90	    for (let i = startPos; i < this.messages.length; ++i) {
91	      const item = this.messages[i];
92	      const role = item[0];
93	      const role_str = item[1];
94	      const messageContent = item[2];
95	
96	      // 1. Message from `appendReplyHeader()`, message is empty; not much processing is needed.
97	      if (messageContent === undefined) {
98	        if (i !== this.messages.length - 1) {
99	          throw new Error(
100	            "InternalError: Only expect message to be undefined for last " +
101	              "message for a reply header.",
102	          );
103	        }
104	        // Add ": " if there is no such field. If "", do not add sep
105	        const empty_sep =
106	          this.config.role_empty_sep || this.config.role_empty_sep == ""
107	            ? this.config.role_empty_sep
108	            : ": ";
109	        ret.push(role_str + empty_sep);
110	        continue;
111	      }
112	
113	      // 2. Message from `appendEmptyThinkingReplyHeader()`, message is an empty thinking block.
114	      if (
115	        this.isLastMessageEmptyThinkingReplyHeader &&
116	        i === this.messages.length - 1
117	      ) {
118	        // TODO(Charlie): content_sep or empty_sep? For Qwen3, both are "\n".
119	        const content_sep =
120	          this.config.role_content_sep || this.config.role_content_sep == ""
121	            ? this.config.role_content_sep
122	            : ": ";
123	        ret.push(role_str + content_sep + messageContent);
124	        continue;
125	      }
126	
127	      // 3. Each messageContent consists of one textPart, and >= 0 imageParts, regardless whether
128	      // it is Array<ChatCompletionContentPart> or text message. So we extract out each.
129	      let textContentPart = ""; // if no textPart, use an empty string
130	      const imageContentParts: ImageURL[] = [];
131	      if (Array.isArray(messageContent)) {
132	        // 2.1 content is Array<ChatCompletionContentPart>
133	        // Iterate through the contentParts, get the text and list of images. There should
134	        // be only a single text. TODO: is it always the case the number of textContentPart <= 1?
135	        let seenText = false;
136	        for (let i = 0; i < messageContent.length; i++) {
137	          const curContentPart = messageContent[i];
138	          if (curContentPart.type === "text") {
139	            if (seenText) {
140	              throw new MultipleTextContentError();
141	            }
142	            textContentPart = curContentPart.text;
143	            seenText = true;
144	          } else {
145	            imageContentParts.push(curContentPart.image_url);
146	          }
147	        }
148	      } else {
149	        // 2.2 content is just a string
150	        textContentPart = messageContent;
151	      }
152	
153	      // 3. Format textContentPart with role and sep to get message_str and role_prefix
154	      let message_str;
155	      let role_prefix;
156	      if (this.config.role_templates !== undefined) {
157	        message_str = this.config.role_templates[role]?.replace(
158	          MessagePlaceholders[Role[role] as keyof typeof MessagePlaceholders],
159	          textContentPart,
160	        );
161	        if (this.use_function_calling && this.function_string !== "") {
162	          message_str = message_str?.replace(
163	            MessagePlaceholders.function,
164	            this.function_string,
165	          );
166	        }
167	        message_str = message_str?.replace(MessagePlaceholders.function, "");
168	      }
169	
170	      if (message_str == undefined) {
171	        message_str = textContentPart;
172	      }
173	      if (
174	        this.config.add_role_after_system_message === false &&
175	        system_prompt != "" &&
176	        i == 0
177	      ) {
178	        role_prefix = "";
179	      } else {
180	        // Add ": " if there is no such field. If "", do not add sep
181	        const content_sep =
182	          this.config.role_content_sep || this.config.role_content_sep == ""
183	            ? this.config.role_content_sep
184	            : ": ";
185	        role_prefix = role_str + content_sep;
186	      }
187	
188	      // 4. Combine everything together
189	      if (imageContentParts.length === 0) {
190	        // If no image, just a single string to represent this message
191	        ret.push(
192	          role_prefix +
193	            message_str +
194	            this.config.seps[i % this.config.seps.length],
195	        );
196	      } else {
197	        // Per-model image layout
198	        const curMessageList: Array<string | ImageURL> = [role_prefix];
199	        const modelType = config?.model_type ?? "";
200	        imageContentParts.forEach((curImage: ImageURL) => {
201	          if (modelType === "phi3_v") {
